const outputText = $json["output"]; // Replace with your field name if different

const emailBlocks = outputText.split(/--- EMAIL \d+ ---/).filter(Boolean);

const drafts = emailBlocks.map(block => {
  const contactName = block.match(/Contact Name:\s*(.+)/)?.[1]?.trim() || "";
  const role = block.match(/Role:\s*(.+)/)?.[1]?.trim() || "";
  const emailId = block.match(/Email ID:\s*(.+)/)?.[1]?.trim() || "";
  const subject = block.match(/Subject:\s*(.+)/)?.[1]?.trim() || "";

  const bodyStart = block.indexOf("Dear ");
  const body = bodyStart !== -1 ? block.substring(bodyStart).trim() : "";

  return {
    contactName,
    role,
    emailId,
    subject,
    body
  };
});

return drafts.map(d => ({ json: d }));
